            { q: "Схема: ввести a; если a нечётное, то s = a + 1, иначе s = a. При a = 9 чему равно s?", answer: "10", steps: ["9 нечётное, условие истинно.", "Выполняется ветвь «да»: s = 9 + 1.", "s = 10."] },
            { q: "Схема: s = 0; повторить 4 раза: s = s + 3. Чему равно s?", answer: "12", steps: ["Каждый повтор прибавляет 3.", "Четыре повтора дают 4 * 3 = 12.", "s = 12."] }
